function hash(v){return crypto.createHash("sha256").update(v).digest("hex");}
function equal(a,b){const x=Buffer.from(String(a||"")),y=Buffer.from(String(b||""));return x.length===y.length&&crypto.timingSafeEqual(x,y);}
function cookies(req){const o={};for(const p of (req.headers.cookie||"").split(";")){const i=p.indexOf("=");if(i>0)o[p.slice(0,i).trim()]=decodeURIComponent(p.slice(i+1).trim());}return o;}
function slug(s){return String(s).toLowerCase().normalize("NFKD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"").slice(0,48)||"hotel";}
async function pwHash(p){const salt=crypto.randomBytes(16).toString("hex");return salt+":"+Buffer.from(await scrypt(p,salt,64)).toString("hex");}
async function pwCheck(p,stored){const a=String(stored||"").split(":");if(a.length!==2)return false;return equal(Buffer.from(await scrypt(p,a[0],64)).toString("hex"),a[1]);}
function requireDb(_q,r,n){if(!db)return r.status(503).json({error:"DATABASE_URL is not configured."});n();}
function setCookie(r,t){r.cookie(cookie,t,{httpOnly:true,secure:prod,sameSite:"strict",path:"/",maxAge:43200000});}
async function auth(q,r,n){
 try{
  const t=cookies(q)[cookie];if(!t)return r.status(401).json({error:"Sign in required."});
  const x=await db.query("SELECT s.id AS session_id,s.csrf_hash,u.id AS user_id,u.email,u.role,u.organization_id,o.name AS organization_name,o.slug AS organization_slug FROM sessions s JOIN users u ON u.id=s.user_id JOIN organizations o ON o.id=u.organization_id WHERE s.token_hash=$1 AND s.expires_at>now() AND u.active=true AND o.status<>'suspended'",[hash(t)]);
  if(!x.rowCount)return r.status(401).json({error:"Session expired. Sign in again."});
  q.actor=x.rows[0];
  if(!["GET","HEAD","OPTIONS"].includes(q.method)&&(!q.get("X-CSRF-Token")||!equal(hash(q.get("X-CSRF-Token")),q.actor.csrf_hash)))return r.status(403).json({error:"Request verification failed."});
  n();
 }catch(e){n(e);}
}
function role(){const ok=Array.from(arguments);return(q,r,n)=>ok.includes(q.actor.role)?n():r.status(403).json({error:"Insufficient permissions."});}
async function audit(a,action,type,id){await db.query("INSERT INTO audit_logs(organization_id,actor_user_id,action,target_type,target_id) VALUES($1,$2,$3,$4,$5)",[a.organization_id,a.user_id,action,type||null,id||null]);}
app.use("/api/admin/storage",requireDb,createStorageRouter({db,auth,role,audit}));
const escalate=requiresStaffEscalation;
async function notify(org,cid,reason){
 if(!process.env.STAFF_WEBHOOK_URL||!process.env.STAFF_WEBHOOK_SECRET)return{configured:false,delivered:false,status:"not_configured"};
 try{const body=JSON.stringify({event:"veyra.escalation.created",organizationId:org.id,organizationSlug:org.slug,organization:org.name,conversationId:cid,reason,createdAt:new Date().toISOString()});const sig=crypto.createHmac("sha256",process.env.STAFF_WEBHOOK_SECRET).update(body).digest("hex");const ctl=new AbortController();const timer=setTimeout(()=>ctl.abort(),5000);try{const resp=await fetch(process.env.STAFF_WEBHOOK_URL,{method:"POST",headers:{"content-type":"application/json","x-veyra-signature":sig},body,signal:ctl.signal});return{configured:true,delivered:resp.ok,status:resp.ok?"delivered":"failed"};}finally{clearTimeout(timer);}}catch(e){console.error("Webhook failed:",e.message);return{configured:true,delivered:false,status:"failed"};}
}
async function readinessSnapshot(){let database="not-configured";if(db){try{await db.query("SELECT 1");database="connected";}catch{database="unavailable";}}const guestDataStorage=process.env.GUEST_DATA_STORAGE_ENABLED==="true",humanHandoff=Boolean(process.env.STAFF_WEBHOOK_URL&&process.env.STAFF_WEBHOOK_SECRET);const gate=buildPilotReadiness({databaseConnected:database==="connected",aiConfigured:Boolean(ai),guestDataStorageEnabled:guestDataStorage,staffWebhookConfigured:humanHandoff,durableBackupsVerified:process.env.DURABLE_BACKUPS_VERIFIED==="true",tenantIsolationTestsPassed:process.env.TENANT_ISOLATION_TESTS_PASSED==="true",providerOAuthTested:process.env.PROVIDER_OAUTH_TESTED==="true",hotelPrivacyApproved:process.env.HOTEL_PRIVACY_APPROVED==="true",staffHandoffTested:process.env.STAFF_HANDOFF_TESTED==="true",pilotReleaseApproved:process.env.PILOT_RELEASE_APPROVED==="true"});return{service:"Veyra AI",mode:ai?"ai-configured":"demo-no-api-key",model:ai?MODEL:null,database,multiTenant:database==="connected",guestDataStorage,humanHandoff:humanHandoff?"webhook-configured":"not-configured",readyForPilot:gate.readyForPilot,checks:gate.checks};}
app.get("/api/health",async(_q,r)=>{const state=await readinessSnapshot();r.status(200).json({status:state.readyForPilot?"ready":"degraded",...state});});
app.get("/api/readiness",async(_q,r)=>{const state=await readinessSnapshot();r.status(state.readyForPilot?200:503).json({status:state.readyForPilot?"ready":"not-ready",...state});});
app.post("/api/setup/organization",requireDb,async(q,r,n)=>{
 try{
  if(!process.env.BOOTSTRAP_TOKEN||!equal(q.get("X-Bootstrap-Token"),process.env.BOOTSTRAP_TOKEN))return r.status(403).json({error:"Bootstrap token invalid or disabled."});
  const b=q.body||{};if(typeof b.organizationName!=="string"||b.organizationName.trim().length<2||b.organizationName.length>100)return r.status(400).json({error:"Valid organization name required."});
  if(typeof b.email!=="string"||!/^[-.+\w]+@[-.\w]+\.[A-Za-z]{2,}$/.test(b.email)||b.email.length>254)return r.status(400).json({error:"Valid email required."});
  if(typeof b.password!=="string"||b.password.length<12||b.password.length>200)return r.status(400).json({error:"Password must be at least 12 characters."});
  const c=await db.connect();try{await c.query("BEGIN");await c.query("SELECT pg_advisory_xact_lock(20261111)");const count=await c.query("SELECT count(*)::int AS n FROM users");if(count.rows[0].n>0){await c.query("ROLLBACK");return r.status(409).json({error:"Initial setup already completed."});}
   const o=await c.query("INSERT INTO organizations(name,slug) VALUES($1,$2) RETURNING id,name,slug",[b.organizationName.trim(),slug(b.organizationName)]);
   const u=await c.query("INSERT INTO users(organization_id,email,password_hash,role) VALUES($1,lower($2),$3,'owner') RETURNING email",[o.rows[0].id,b.email,await pwHash(b.password)]);
   await c.query("INSERT INTO audit_logs(organization_id,action,target_type) VALUES($1,'organization.created','organization')",[o.rows[0].id]);await c.query("COMMIT");
   r.status(201).json({organization:{name:o.rows[0].name,slug:o.rows[0].slug},owner:{email:u.rows[0].email},message:"Owner created. Remove BOOTSTRAP_TOKEN and sign in."});
  }catch(e){await c.query("ROLLBACK");throw e;}finally{c.release();}
 }catch(e){n(e);}
});
app.post("/api/platform/organizations",requireDb,async(q,r,n)=>{
 try{
  const secret=process.env.PLATFORM_PROVISIONING_TOKEN;
  if(!secret||!equal(q.get("X-Platform-Provisioning-Token"),secret))return r.status(403).json({error:"Platform provisioning is not authorized."});
  const b=q.body||{};
  if(typeof b.organizationName!=="string"||b.organizationName.trim().length<2||b.organizationName.length>100)return r.status(400).json({error:"Valid organization name required."});
  if(typeof b.email!=="string"||!/^[-.+\w]+@[-.\w]+\.[A-Za-z]{2,}$/.test(b.email)||b.email.length>254)return r.status(400).json({error:"Valid owner email required."});
  if(typeof b.password!=="string"||b.password.length<12||b.password.length>200)return r.status(400).json({error:"Owner password must be 12–200 characters."});
  const organizationSlug=slug(b.organizationName);
  const c=await db.connect();
  try{
   await c.query("BEGIN");
   await c.query("SELECT pg_advisory_xact_lock(20261112)");
   const exists=await c.query("SELECT id FROM organizations WHERE slug=$1",[organizationSlug]);
   if(exists.rowCount){await c.query("ROLLBACK");return r.status(409).json({error:"A hotel workspace with that name already exists. Choose a distinct hotel name."});}
   const o=await c.query("INSERT INTO organizations(name,slug) VALUES($1,$2) RETURNING id,name,slug",[b.organizationName.trim(),organizationSlug]);
   const u=await c.query("INSERT INTO users(organization_id,email,password_hash,role) VALUES($1,lower($2),$3,'owner') RETURNING email",[o.rows[0].id,b.email,await pwHash(b.password)]);
   await c.query("INSERT INTO audit_logs(organization_id,action,target_type) VALUES($1,'organization.created','organization')",[o.rows[0].id]);
   await c.query("COMMIT");
   r.status(201).json({organization:{name:o.rows[0].name,slug:o.rows[0].slug},owner:{email:u.rows[0].email},message:"Hotel workspace created. Its owner can now sign in using this workspace slug."});
  }catch(e){await c.query("ROLLBACK");if(e.code==="23505")return r.status(409).json({error:"That hotel workspace or owner email already exists."});throw e;}finally{c.release();}
 }catch(e){n(e);}
});
app.post("/api/auth/login",requireDb,async(q,r,n)=>{
 try{const b=q.body||{};if(typeof b.email!=="string"||typeof b.password!=="string"||typeof b.organizationSlug!=="string"||b.email.length>254||b.password.length>200||!/^[a-z0-9-]{1,48}$/.test(b.organizationSlug))return r.status(400).json({error:"Enter workspace slug, email and password."});
  const x=await db.query("SELECT u.id,u.email,u.password_hash,u.role FROM users u JOIN organizations o ON o.id=u.organization_id WHERE u.email=lower($1) AND o.slug=$2 AND u.active=true AND o.status<>'suspended' LIMIT 2",[b.email,b.organizationSlug]);
  if(x.rowCount!==1||!(await pwCheck(b.password,x.rows[0].password_hash)))return r.status(401).json({error:"Email or password is incorrect."});
  const t=crypto.randomBytes(32).toString("base64url"),csrf=crypto.randomBytes(24).toString("base64url");
  await db.query("INSERT INTO sessions(user_id,token_hash,csrf_hash,expires_at) VALUES($1,$2,$3,now()+interval '12 hours')",[x.rows[0].id,hash(t),hash(csrf)]);setCookie(r,t);
  r.json({user:{email:x.rows[0].email,role:x.rows[0].role},csrfToken:csrf});
 }catch(e){n(e);}
});
app.post("/api/auth/logout",requireDb,auth,async(q,r,n)=>{try{await db.query("DELETE FROM sessions WHERE id=$1",[q.actor.session_id]);r.clearCookie(cookie,{path:"/",secure:prod,sameSite:"strict"});r.json({ok:true});}catch(e){n(e);}});
