app.put("/api/admin/settings",requireDb,auth,role("owner","admin"),async(q,r,n)=>{try{const b=q.body||{};let website=typeof b.website_url==="string"?b.website_url.trim():"";const email=typeof b.support_email==="string"?b.support_email.trim().toLowerCase():"";const timezone=typeof b.timezone==="string"?b.timezone.trim():"UTC";const language=typeof b.language==="string"?b.language.trim().toLowerCase():"en";const fallback=typeof b.fallback_instructions==="string"?b.fallback_instructions.trim():"";if(website){let u;try{u=new URL(website);}catch{return r.status(400).json({error:"Enter a valid hotel website URL."});}if(u.protocol!=="https:"||u.username||u.password||u.pathname!=="/"||u.search||u.hash)return r.status(400).json({error:"Use the hotel's HTTPS website origin only, for example https://hotel.example."});website=u.origin;}if(email&&!/^[-.+\w]+@[-.\w]+\.[A-Za-z]{2,}$/.test(email))return r.status(400).json({error:"Enter a valid staff contact email."});if(email.length>254||fallback.length>1500||!/^([a-z]{2,3})(-[A-Z]{2})?$/.test(language))return r.status(400).json({error:"Check the email, language code and fallback instructions."});try{new Intl.DateTimeFormat("en",{timeZone:timezone});}catch{return r.status(400).json({error:"Enter a valid IANA time zone, such as Asia/Bangkok."});}const x=await db.query("INSERT INTO organization_settings(organization_id,website_url,support_email,timezone,language,fallback_instructions,updated_by,updated_at) VALUES($1,$2,$3,$4,$5,$6,$7,now()) ON CONFLICT(organization_id) DO UPDATE SET website_url=EXCLUDED.website_url,support_email=EXCLUDED.support_email,timezone=EXCLUDED.timezone,language=EXCLUDED.language,fallback_instructions=EXCLUDED.fallback_instructions,updated_by=EXCLUDED.updated_by,updated_at=now() RETURNING website_url,support_email,timezone,language,fallback_instructions,updated_at",[q.actor.organization_id,website,email,timezone,language,fallback,q.actor.user_id]);await audit(q.actor,"workspace.settings_updated","organization_settings",q.actor.organization_id);r.json({settings:x.rows[0]});}catch(e){n(e);}});

app.get("/api/admin/retention",requireDb,auth,async(q,r,n)=>{try{const setting=await db.query("SELECT conversation_retention_days FROM organization_settings WHERE organization_id=$1",[q.actor.organization_id]);const days=setting.rows[0]?.conversation_retention_days||0;if(!days)return r.json({retentionDays:0,enabled:false,eligibleConversations:0,note:"Retention cleanup is disabled until the hotel owner sets a retention period."});const count=await db.query("SELECT count(*)::int AS eligible FROM conversations c WHERE c.organization_id=$1 AND c.status='resolved' AND c.last_message_at<now()-($2::int*interval '1 day') AND NOT EXISTS(SELECT 1 FROM escalations e WHERE e.conversation_id=c.id AND e.status<>'resolved')",[q.actor.organization_id,days]);r.json({retentionDays:days,enabled:true,eligibleConversations:count.rows[0].eligible,note:"Only resolved conversations past the configured period with no open escalation are eligible."});}catch(e){n(e);}});
app.put("/api/admin/retention",requireDb,auth,role("owner","admin"),async(q,r,n)=>{try{const days=q.body?.retentionDays;if(!Number.isInteger(days)||![0,30,60,90,180,365,730,1095,1825,3650].includes(days))return r.status(400).json({error:"Choose 0 (disabled) or one of the supported retention periods."});await db.query("INSERT INTO organization_settings(organization_id,conversation_retention_days,updated_by,updated_at) VALUES($1,$2,$3,now()) ON CONFLICT(organization_id) DO UPDATE SET conversation_retention_days=EXCLUDED.conversation_retention_days,updated_by=EXCLUDED.updated_by,updated_at=now()",[q.actor.organization_id,days,q.actor.user_id]);await audit(q.actor,"retention.policy_updated","organization_settings",q.actor.organization_id);r.json({retentionDays:days,enabled:days>0});}catch(e){n(e);}});
app.post("/api/admin/retention/cleanup",requireDb,auth,role("owner","admin"),async(q,r,n)=>{if(q.body?.confirm!==true)return r.status(400).json({error:"Explicit confirmation is required."});try{const setting=await db.query("SELECT conversation_retention_days FROM organization_settings WHERE organization_id=$1",[q.actor.organization_id]);const days=setting.rows[0]?.conversation_retention_days||0;if(!days)return r.status(409).json({error:"Retention is disabled for this hotel."});const c=await db.connect();try{await c.query("BEGIN");const result=await c.query("WITH candidates AS MATERIALIZED (SELECT c.id FROM conversations c WHERE c.organization_id=$1 AND c.status='resolved' AND c.last_message_at<now()-($2::int*interval '1 day') AND NOT EXISTS(SELECT 1 FROM escalations e WHERE e.conversation_id=c.id AND e.status<>'resolved') ORDER BY c.last_message_at ASC LIMIT 500 FOR UPDATE SKIP LOCKED), detached AS (UPDATE revenue_events re SET conversation_id=NULL,attribution_status='hotel_reported_unlinked' WHERE re.organization_id=$1 AND re.conversation_id IN (SELECT id FROM candidates) RETURNING re.id), deleted AS (DELETE FROM conversations c USING candidates x WHERE c.id=x.id AND c.organization_id=$1 RETURNING c.id) SELECT count(*)::int AS deleted FROM deleted",[q.actor.organization_id,days]);const remaining=await c.query("SELECT count(*)::int AS eligible FROM conversations c WHERE c.organization_id=$1 AND c.status='resolved' AND c.last_message_at<now()-($2::int*interval '1 day') AND NOT EXISTS(SELECT 1 FROM escalations e WHERE e.conversation_id=c.id AND e.status<>'resolved')",[q.actor.organization_id,days]);await c.query("INSERT INTO audit_logs(organization_id,actor_user_id,action,target_type,target_id) VALUES($1,$2,'retention.cleanup_executed','conversation_batch',$3)",[q.actor.organization_id,q.actor.user_id,String(result.rows[0].deleted)]);await c.query("COMMIT");r.json({deleted:result.rows[0].deleted,remainingEligible:remaining.rows[0].eligible,retentionDays:days,batchLimit:500});}catch(e){await c.query("ROLLBACK");throw e;}finally{c.release();}}catch(e){n(e);}});
app.get("/api/admin/onboarding",requireDb,auth,async(q,r,n)=>{try{const [profile,knowledge,storage,integrationChecks]=await Promise.all([db.query("SELECT website_url,support_email,timezone,language FROM organization_settings WHERE organization_id=$1",[q.actor.organization_id]),db.query("SELECT count(*)::int AS approved_count FROM knowledge_documents WHERE organization_id=$1 AND approved=true AND (review_due_at IS NULL OR review_due_at>=CURRENT_DATE)",[q.actor.organization_id]),db.query("SELECT status,provider FROM organization_storage_connections WHERE organization_id=$1 ORDER BY connected_at DESC LIMIT 1",[q.actor.organization_id]),db.query("SELECT integration,verified_at FROM organization_integration_checks WHERE organization_id=$1 AND verified_at>now()-interval '30 days'",[q.actor.organization_id])]);const p=profile.rows[0]||{website_url:"",support_email:"",timezone:"UTC",language:"en"};let originAllowed=false;if(p.website_url){try{const u=new URL(p.website_url);originAllowed=u.protocol==="https:"&&u.origin===p.website_url;}catch{}}const verified=Object.fromEntries(integrationChecks.rows.map(x=>[x.integration,x.verified_at]));const aiVerified=Boolean(ai&&verified.ai_provider),handoffConfigured=Boolean(process.env.STAFF_WEBHOOK_URL&&process.env.STAFF_WEBHOOK_SECRET),handoffVerified=Boolean(handoffConfigured&&verified.staff_webhook);const checks=[{key:"profile",label:"Hotel profile",done:Boolean(p.website_url&&p.support_email),detail:p.website_url&&p.support_email?"Website and staff contact saved.":"Add the official HTTPS website and a staff contact email."},{key:"knowledge",label:"Approved hotel knowledge",done:knowledge.rows[0].approved_count>0,detail:knowledge.rows[0].approved_count+" approved document(s). A manager must verify every fact."},{key:"ai",label:"AI provider",done:aiVerified,detail:!ai?"OPENAI_API_KEY is not configured on the server.":aiVerified?"The configured model was verified for this hotel.":"Run the AI connection test for this hotel."},{key:"origin",label:"Hotel website CORS",done:originAllowed,detail:originAllowed?"This hotel's saved HTTPS origin is automatically allowed for its own widget.":"Save the hotel's exact HTTPS website origin in its profile."},{key:"handoff",label:"Staff notification",done:handoffVerified,detail:!handoffConfigured?"Configure the signed staff notification dispatcher.":handoffVerified?"A signed test event was accepted for this hotel.":"Run a test handoff for this hotel."},{key:"hotel_storage",label:"Hotel-owned storage connection",done:storage.rowCount>0&&storage.rows[0].status==="connected",detail:storage.rowCount?storage.rows[0].provider+" is "+storage.rows[0].status+". OAuth and sync must be verified before this is complete.":"Choose and authorize a hotel storage provider."},{key:"privacy",label:"Privacy and durable storage approval",done:process.env.GUEST_DATA_STORAGE_ENABLED==="true",detail:process.env.GUEST_DATA_STORAGE_ENABLED==="true"?"Storage is enabled; confirm written hotel approval, retention, backups and deletion process.":"Guest-data storage is safely disabled until privacy and retention approval."}];const readyForPilot=checks.every(x=>x.done);r.json({checks,readyForPilot,approvedKnowledgeCount:knowledge.rows[0].approved_count,settings:p,notice:"This checklist is operational guidance, not a legal or security certification. Do not use real guest data until the hotel has approved privacy, retention, backup and staff-response arrangements."});}catch(e){n(e);}});
app.post("/api/admin/integrations/test-ai",requireDb,auth,role("owner","admin"),integrationTestLimiter,async(q,r,n)=>{try{if(!ai)return r.status(503).json({verified:false,error:"OPENAI_API_KEY is not configured on the server."});const model=await ai.models.retrieve(MODEL,{timeout:10000});await db.query("INSERT INTO organization_integration_checks(organization_id,integration,verified_at,verified_by) VALUES($1,'ai_provider',now(),$2) ON CONFLICT(organization_id,integration) DO UPDATE SET verified_at=now(),verified_by=EXCLUDED.verified_by",[q.actor.organization_id,q.actor.user_id]);await audit(q.actor,"integration.ai_provider_verified","integration",MODEL);r.json({verified:true,model:model.id||MODEL});}catch(e){console.error("AI provider verification failed:",e.message);r.status(502).json({verified:false,error:"The configured AI provider or model could not be verified. Check the server-side key and model access."});}});
app.post("/api/admin/integrations/test-staff-webhook",requireDb,auth,role("owner","admin"),integrationTestLimiter,async(q,r,n)=>{try{if(!process.env.STAFF_WEBHOOK_URL||!process.env.STAFF_WEBHOOK_SECRET)return r.status(503).json({verified:false,error:"Staff notification dispatcher is not configured."});const event={event:"veyra.integration.test",test:true,organizationId:q.actor.organization_id,organizationSlug:q.actor.organization_slug,organization:q.actor.organization_name,createdAt:new Date().toISOString()};const body=JSON.stringify(event);const signature=crypto.createHmac("sha256",process.env.STAFF_WEBHOOK_SECRET).update(body).digest("hex");const response=await fetch(process.env.STAFF_WEBHOOK_URL,{method:"POST",headers:{"content-type":"application/json","x-veyra-signature":signature},body,signal:AbortSignal.timeout(5000)});if(!response.ok)return r.status(502).json({verified:false,error:"The staff notification receiver did not accept the test event."});await db.query("INSERT INTO organization_integration_checks(organization_id,integration,verified_at,verified_by) VALUES($1,'staff_webhook',now(),$2) ON CONFLICT(organization_id,integration) DO UPDATE SET verified_at=now(),verified_by=EXCLUDED.verified_by",[q.actor.organization_id,q.actor.user_id]);await audit(q.actor,"integration.staff_webhook_verified","integration",q.actor.organization_id);r.json({verified:true,event:"veyra.integration.test",organizationSlug:q.actor.organization_slug});}catch(e){console.error("Staff webhook verification failed:",e.message);r.status(502).json({verified:false,error:"Could not reach the staff notification receiver. Check its URL and secret."});}});
