async function start(){if(db){await db.query(schema);try{await db.query("ALTER TABLE revenue_events ADD CONSTRAINT revenue_events_conversation_id_fkey FOREIGN KEY(conversation_id) REFERENCES conversations(id) ON DELETE SET NULL");}catch(e){if(e.code!=="42710")throw e;}await db.query("DELETE FROM sessions WHERE expires_at<now()");await db.query("DELETE FROM storage_oauth_states WHERE expires_at<now()");}app.listen(PORT,"0.0.0.0",()=>console.log("Veyra listening on "+PORT+(db?" with PostgreSQL":" in demo mode")));}
start().catch(e=>{console.error("Startup failed:",e.message);process.exit(1);});
